mapper.select:
SELECT d.id, d.project_id, p.name AS project_name, d.name, d.category,
       d.current_version, d.status, d.file_size, d.file_format,
       d.uploader_name, DATE_FORMAT(d.upload_date, '%Y-%m-%d') AS upload_date,
       d.description,
       su.name AS reviewer_name,
       DATE_FORMAT(d.review_time, '%Y-%m-%d %H:%i') AS review_time,
       d.review_remark
FROM biz_document d
LEFT JOIN biz_project p ON d.project_id = p.id
LEFT JOIN sys_user su ON d.reviewer_id = su.id


        AND (d.name LIKE CONCAT('%', #{query.keyword}, '%')
          OR d.description LIKE CONCAT('%', #{query.keyword}, '%'))


        AND d.category = #{query.category}


        AND d.project_id = #{query.projectId}


        AND d.status = #{query.status}


        AND d.file_format = #{query.fileType}


        AND d.uploader_name LIKE CONCAT('%', #{query.uploader}, '%')


        AND d.upload_date >= #{query.uploadDateBegin}


        AND d.upload_date <= #{query.uploadDateEnd}


        AND 1 = 0


        AND d.project_id IN

            #{pid}



ORDER BY d.upload_date DESC, d.id DESC
